const UAParser = require('ua-parser-js');
const crypto = require('crypto');
const logger = require('../utils/logger');
const { query } = require('../db');
const statsService = require('./statsService');
const backendRoleService = require('./backendRoleService');
const { clampText, maskIp, normalizeIngestPath } = require('../utils/analyticsUtils');

const UUID_REGEX =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

const LEGACY_WEB_MIRROR_ENABLED = String(process.env.ANALYTICS_WEB_LEGACY_MIRROR_ENABLED || 'true').toLowerCase() !== 'false';

// Short-window idempotency hashes for high-risk web events.
//
// The unified `public.analytics_events` insert uses `ON CONFLICT DO NOTHING`,
// so a stable `dedupe_hash` collapses duplicates that arrive with *different*
// client event ids (route remounts, hydration double-fires, fallback retries).
// Each event type has a partial unique index on `dedupe_hash` (see migration
// 073_analytics_events_dedupe_indexes.sql). Window sizes are intentionally
// small so legitimate distinct interactions are never merged.
const DEDUPE_WINDOWS_MS = Object.freeze({
  page_view: 5000, // 5s
  conversion: 30000, // 30s
  cta_click: 2000, // 2s
  form_success: 30000, // 30s
  // form_start / section_impression are deduped once per session (no time bucket).
});

function timeBucket(tsIso, windowMs) {
  const ms = new Date(tsIso).getTime();
  if (!Number.isFinite(ms)) return null;
  return Math.floor(ms / windowMs) * windowMs;
}

function hashParts(parts) {
  return crypto.createHash('sha256').update(parts.join('|')).digest('hex');
}

// Pick the first non-empty string from candidate metadata keys, normalized.
function metaName(metadata, keys) {
  const md = metadata && typeof metadata === 'object' ? metadata : {};
  for (const key of keys) {
    const value = md[key];
    if (typeof value === 'string' && value.trim()) {
      return value.trim().toLowerCase().slice(0, 128);
    }
  }
  return '';
}

// Build the dedupe hash for a web event. Returns null when the event type is
// not deduped or required signal (session/path) is missing.
function buildWebDedupeHash({ site, eventName, sessionId, path, metadata, tsIso }) {
  if (!site || !sessionId) return null;

  switch (eventName) {
    case 'page_view': {
      if (!path) return null;
      const bucket = timeBucket(tsIso, DEDUPE_WINDOWS_MS.page_view);
      if (bucket === null) return null;
      // Exclude ingest path so retries across /analytics <-> /a still dedupe.
      return hashParts([site, eventName, sessionId, path, bucket]);
    }
    case 'conversion': {
      const bucket = timeBucket(tsIso, DEDUPE_WINDOWS_MS.conversion);
      if (bucket === null) return null;
      const name = metaName(metadata, ['name', 'conversion', 'conversionName']);
      return hashParts([site, eventName, sessionId, path || '', name, bucket]);
    }
    case 'cta_click': {
      const bucket = timeBucket(tsIso, DEDUPE_WINDOWS_MS.cta_click);
      if (bucket === null) return null;
      const name = metaName(metadata, ['cta', 'ctaName', 'name']);
      return hashParts([site, eventName, sessionId, path || '', name, bucket]);
    }
    case 'form_success': {
      const bucket = timeBucket(tsIso, DEDUPE_WINDOWS_MS.form_success);
      if (bucket === null) return null;
      const name = metaName(metadata, ['form', 'formName', 'name']);
      return hashParts([site, eventName, sessionId, path || '', name, bucket]);
    }
    case 'form_start': {
      // Once per form per session.
      const name = metaName(metadata, ['form', 'formName', 'name']);
      return hashParts([site, eventName, sessionId, path || '', name]);
    }
    case 'section_impression': {
      // Once per section per session/page.
      const name = metaName(metadata, ['section', 'sectionName', 'name']);
      return hashParts([site, eventName, sessionId, path || '', name]);
    }
    case 'web_vital': {
      // Once per metric instance per session (metric id is unique per page load).
      const id = metaName(metadata, ['id', 'metricId']);
      const name = metaName(metadata, ['name', 'metric', 'metricName']);
      return hashParts([site, eventName, sessionId, id, name]);
    }
    default:
      return null;
  }
}

const parseUserAgent = (uaRaw) => {
  const ua = (uaRaw || '').toString();
  if (!ua) {
    return {
      uaRaw: null,
      browser: null,
      os: null,
      device: null,
    };
  }

  const parser = new UAParser(ua);
  const result = parser.getResult();

  const browser = clampText(
    [result.browser.name, result.browser.version].filter(Boolean).join(' '),
    128,
  );
  const os = clampText([result.os.name, result.os.version].filter(Boolean).join(' '), 128);

  const deviceType = result.device.type || 'desktop';
  const device = clampText(
    [deviceType, result.device.vendor, result.device.model].filter(Boolean).join(' '),
    128,
  );

  return {
    uaRaw: clampText(ua, 512),
    browser,
    os,
    device,
  };
};

const requestHeader = (req, name) => {
  if (req && typeof req.get === 'function') {
    return req.get(name);
  }
  return req?.headers?.[name] ?? null;
};

const resolveCountryCode = (req) => {
  for (const headerName of ['cf-ipcountry', 'x-vercel-ip-country']) {
    const rawValue = requestHeader(req, headerName);
    const value = Array.isArray(rawValue) ? rawValue[0] : rawValue;
    const countryCode = `${value || ''}`.trim().toUpperCase();
    if (/^[A-Z]{2}$/.test(countryCode) && countryCode !== 'XX') {
      return countryCode;
    }
  }
  return null;
};

async function trackWebEvent({
  site,
  eventName,
  eventId,
  path,
  referrer,
  title,
  sessionId,
  anonymousId,
  clientTs,
  ingestFallback,
  metadata,
  req,
}) {
  const writableStatus = await backendRoleService.getWritableStatusCached();
  if (!writableStatus?.healthy || !writableStatus?.writable) {
    return;
  }

  const safeSite = clampText(site, 128);
  const safeEvent = clampText(eventName, 64);

  if (!safeSite || !safeEvent) {
    const error = new Error('Missing site or eventName');
    error.statusCode = 400;
    throw error;
  }

  const safePath = clampText(path, 512);
  const safeReferrer = clampText(referrer, 1024);
  const safeTitle = clampText(title, 256);
  const safeSessionId = clampText(sessionId, 128);
  const safeAnonymousId = clampText(anonymousId, 128);
  const safeEventId = clampText(eventId, 64);
  const safeIngestFallback = Boolean(ingestFallback);

  // Privacy rule (fail closed): if we cannot associate events to a persisted session,
  // do not store or count them.
  if (!safeSessionId) return;

  // Idempotency rule (fail closed): require a stable UUID event id for web ingestion.
  const safeEventIdUuid = safeEventId && UUID_REGEX.test(safeEventId) ? safeEventId : null;
  if (!safeEventIdUuid) return;

  const ingestPath = normalizeIngestPath({ req, defaultPath: '/analytics' });

  const ipMasked = maskIp(req && req.ip);
  const uaParsed = parseUserAgent(req && req.get && req.get('user-agent'));
  const countryCode = resolveCountryCode(req);

  let parsedTs = null;
  if (clientTs) {
    const d = new Date(clientTs);
    if (!Number.isNaN(d.getTime())) {
      parsedTs = d.toISOString();
    }
  }

  const safeMetadata = metadata && typeof metadata === 'object' ? metadata : {};

  const tsIso = parsedTs || new Date().toISOString();

  // Defense in depth: short-window idempotency for high-risk web events so
  // duplicate client fires (distinct event ids) collapse via ON CONFLICT.
  const dedupeHash = (() => {
    try {
      return buildWebDedupeHash({
        site: safeSite,
        eventName: safeEvent,
        sessionId: safeSessionId,
        path: safePath,
        metadata: safeMetadata,
        tsIso,
      });
    } catch (_) {
      return null;
    }
  })();

  // Best-effort write into the unified analytics table.
  // Never throw from analytics ingestion (do not block the user experience).
  try {
    const telemetryResult = await statsService.trackAnalyticsEvent({
      property: safeSite,
      eventType: safeEvent,
      eventCategory: 'web',
      eventId: safeEventIdUuid,
      clientType: 'web',
      anonymousId: safeAnonymousId || (typeof safeMetadata.anonymousId === 'string' ? safeMetadata.anonymousId : null),
      sessionId: safeSessionId || (typeof safeMetadata.sessionId === 'string' ? safeMetadata.sessionId : null),
      path: safePath,
      referrer: safeReferrer,
      ts: tsIso,
      ingestPath,
      ingestFallback: safeIngestFallback,
      dedupeHash,
      // Web telemetry must not trigger the legacy minimal insert: that path
      // writes a second, event_id-less row into public.analytics_events for
      // every event (double counting). The expanded insert below is canonical.
      skipLegacyInsert: true,
      metadata: {
        title: safeTitle || undefined,
        country_code: countryCode || undefined,
        ip_masked: ipMasked || undefined,
        ua_browser: uaParsed.browser || undefined,
        ua_os: uaParsed.os || undefined,
        ua_device: uaParsed.device || undefined,
        ...(safeMetadata || {}),
      },
      req,
    });

    if (telemetryResult?.skipped) {
      return;
    }
  } catch (e) {
    logger.warn('webAnalyticsService.trackWebEvent analytics_events insert failed', { error: e.message });
  }

  if (LEGACY_WEB_MIRROR_ENABLED) {
    try {
      await query(
        `INSERT INTO public.web_analytics_events
          (site, event_name, path, referrer, title, session_id, client_ts, ip_masked, ua_browser, ua_os, ua_device, ua_raw, country_code, metadata)
         VALUES
          ($1, $2, $3, $4, $5, $6, $7::timestamptz, $8::inet, $9, $10, $11, $12, $13, $14::jsonb)`,
        [
          safeSite,
          safeEvent,
          safePath,
          safeReferrer,
          safeTitle,
          safeSessionId,
          parsedTs,
          ipMasked,
          uaParsed.browser,
          uaParsed.os,
          uaParsed.device,
          uaParsed.uaRaw,
          countryCode,
          JSON.stringify(safeMetadata),
        ],
      );
    } catch (e) {
      logger.warn('webAnalyticsService.trackWebEvent web_analytics_events insert failed', { error: e.message });
    }
  }
}

module.exports = {
  trackWebEvent,
  maskIp,
  buildWebDedupeHash,
  _test: {
    resolveCountryCode,
  },
};
